#include <stdio.h>



int main(void) {
    int c, counts[5] = {0};
    while ((c = getchar()) != EOF && c != '\n') {
        if (c >= 'A' && c <= 'Z') counts[0]++;
        else if (c >= 'a' && c <= 'z') counts[1]++;
        else if (c >= '0' && c <= '9') counts[2]++;
        else if (c == ' ') counts[3]++;
        else counts[4]++;
    }
    printf("%d %d %d %d %d\n", counts[0], counts[1], counts[2], counts[3], counts[4]);
    return 0;
}
